let revealObserver=null;function initInterior(root){revealObserver?.disconnect();if('IntersectionObserver'in window&&!matchMedia('(prefers-reduced-motion: reduce)').matches){revealObserver=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in-view');revealObserver.unobserve(e.target);}});},{threshold:.1});root.querySelectorAll('.interior-reveal, .service-grid .svc').forEach((el,i)=>{el.classList.add('interior-reveal');el.style.setProperty('--stagger',`${(i%3)*65}ms`);revealObserver.observe(el)});}initGeo(root);}
